@startuml

class Resident {
  + Name : string
  + StreetAddress : string
  + PhoneNumber : string
  + Email : string
  + ItemsDescription : string
}

class PickupVehicle {
  + LicensePlateNumber : string
  + AvailableStorageSpace : int
}

class VolunteerDriver {
  + Name : string
  + AvailableDays : date[]
}

class PickupRoute {
  + Vehicle : PickupVehicle
  + Driver : VolunteerDriver
  + ScheduledItems : Item[]
}

class Item {
  + Description : string
  + Category : string
  + RFIDTagged : boolean
}

class DistributionCenter {
  + Address : string
}

class FoodBank {
  + Address : string
}

class H2SEmployee {
  + Name : string
  + QualityCheck : bool
  + AssignedCategories : ItemCategory[]
}

enum ItemCategory {
  BabyClothing
  WomenWinterBoots
  Fridge
  Microwave
  // ... other categories
}

Resident "1" -- "*" PickupRoute : schedules
PickupVehicle "0..*" PickupRoute : has
VolunteerDriver "0..*" PickupRoute : drives
PickupRoute "0..*" Item : contains
DistributionCenter "1" -- "*" Item : receives
FoodBank "1" -- "*" NonPerishableFood : receives

H2SEmployee "1" -- "*" Item : examines
H2SEmployee "1" -- "*" ItemCategory : assigns
H2SEmployee "0..*" Client : calls
Client "1" -- "*" ItemCategory : needs

@enduml

